// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(amount > 0);
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        vm.deal(depositor, amount);

        uint256 balBefore = address(c).balance;
        vm.prank(depositor);
        c.deposit{value: amount}();
        uint256 balAfter = address(c).balance;

        assertTrue(balAfter == balBefore + amount);
    }
}
